import SDKConnector from '../SDKConnector';
import { HTTP_METHODS } from '../common/types';
import log from '../Logger';
import { serviceErrorCodeHandler, uploadLogs } from '../common/Utils';
import { METHOD_START_MESSAGE, SUCCESS_MESSAGE, SUCCESS_STATUS_CODE } from '../common/constants';
import { COMMON_EVENT_KEYS, MOBIUS_EVENT_KEYS, RECORDING_EVENT_SUBTYPE, } from '../Events/types';
import { Eventing } from '../Events/impl';
import { RecordingRequestType, } from './types';
import { CALL_RECORDING_FILE, CATEGORY, DEFAULT_CATEGORY, DEFAULT_MAX, DEFAULT_OFFSET, DEFAULT_ORDER_BY, DEFAULT_ORDER_TYPE, DEFAULT_STATUS, LIMIT, METHODS, OFFSET, ORDER_BY, ORDER_TYPE, RECORDING_NOT_FOUND_MESSAGE, SOFT_DELETE, STATUS, USERHUB_SERVICE_NAME, WEBEX_USER_REQUEST_HEADER, } from './constants';
import { joinUserhubRecordingsUrl, mapUserhubMetadata, mapUserhubRecording, unwrapUserhubRecording, } from './userhub';
function readUserhubErrorDetail(err) {
    if (!err || typeof err !== 'object') {
        return '';
    }
    const body = err.body;
    if (typeof body === 'string') {
        return body.slice(0, 500);
    }
    if (!body || typeof body !== 'object') {
        return '';
    }
    const record = body;
    const parts = [record.errorCode, record.message, record.error, record.trackingId].filter((part) => typeof part === 'string' && part.trim());
    if (parts.length > 0) {
        return parts.join(' ').slice(0, 500);
    }
    try {
        return JSON.stringify(body).slice(0, 500);
    }
    catch {
        return '';
    }
}
export class WxcCallRecordingConnector extends Eventing {
    sdkConnector;
    webex;
    constructor(webex, logger) {
        super();
        this.sdkConnector = SDKConnector;
        if (!this.sdkConnector.getWebex()) {
            SDKConnector.setWebex(webex);
        }
        this.webex = this.sdkConnector.getWebex();
        this.registerRecordingListeners();
        log.setLogger(logger.level, CALL_RECORDING_FILE);
    }
    resolveUserhubBaseUrl() {
        const catalogUrl = this.webex.internal.services._serviceUrls?.[USERHUB_SERVICE_NAME] ||
            (typeof this.webex.internal.services.get === 'function'
                ? this.webex.internal.services.get(USERHUB_SERVICE_NAME)
                : '');
        return joinUserhubRecordingsUrl(catalogUrl || '');
    }
    buildUserhubRecordingsUrl(options) {
        const baseUrl = this.resolveUserhubBaseUrl();
        if (!baseUrl) {
            return '';
        }
        const params = new URLSearchParams();
        params.append(ORDER_TYPE, DEFAULT_ORDER_TYPE);
        params.append(ORDER_BY, DEFAULT_ORDER_BY);
        params.append(STATUS, options?.status ?? DEFAULT_STATUS);
        params.append(CATEGORY, DEFAULT_CATEGORY);
        params.append(OFFSET, DEFAULT_OFFSET);
        params.append(LIMIT, `${options?.max ?? DEFAULT_MAX}`);
        return `${baseUrl}?${params.toString()}`;
    }
    buildUserhubRecordingUrl(recordingId) {
        const baseUrl = this.resolveUserhubBaseUrl();
        if (!baseUrl) {
            return '';
        }
        return `${baseUrl}/${encodeURIComponent(recordingId)}`;
    }
    buildUserhubSoftDeleteUrl() {
        const baseUrl = this.resolveUserhubBaseUrl();
        return baseUrl ? `${baseUrl}/${SOFT_DELETE}` : '';
    }
    async userhubRequest(url, method, body, logMethod = METHODS.GET_RECORDINGS) {
        if (!url) {
            const error = new Error('User Hub recordings URL is empty');
            error.statusCode = 503;
            throw error;
        }
        const supertoken = this.webex.credentials
            .supertoken;
        if (supertoken) {
            return this.userhubFetch(url, method, body, supertoken);
        }
        try {
            return await this.webex.request({
                uri: url,
                method,
                headers: {
                    Accept: 'application/json',
                    [WEBEX_USER_REQUEST_HEADER]: 'true',
                },
                ...(body ? { body } : {}),
            });
        }
        catch (error) {
            const statusCode = Number(error?.statusCode);
            if (statusCode !== 500) {
                throw error;
            }
            log.info('User Hub returned 500 from webex.request; retrying with the user token only', {
                file: CALL_RECORDING_FILE,
                method: logMethod,
            });
            return this.userhubFetch(url, method, body);
        }
    }
    async userhubFetch(url, method, body, tokenOverride) {
        const token = tokenOverride ?? (await this.webex.credentials.getUserToken());
        const rendered = String(token);
        const authorization = /^Bearer\s/i.test(rendered) ? rendered : `Bearer ${rendered}`;
        const headers = {
            Accept: 'application/json',
            Authorization: authorization,
            [WEBEX_USER_REQUEST_HEADER]: 'true',
        };
        if (body) {
            headers['Content-Type'] = 'application/json';
        }
        const response = await fetch(url, {
            method,
            headers,
            ...(body ? { body: JSON.stringify(body) } : {}),
        });
        const text = await response.text();
        let parsed;
        if (text) {
            try {
                parsed = JSON.parse(text);
            }
            catch {
                parsed = { message: text };
            }
        }
        const payload = {
            statusCode: response.status,
            body: parsed,
        };
        if (!response.ok) {
            throw payload;
        }
        return payload;
    }
    getCallRecording(request) {
        return this.dispatchGetCallRecording(request);
    }
    dispatchGetCallRecording(request) {
        switch (request.type) {
            case RecordingRequestType.LIST:
                return this.getRecordings(request.options);
            case RecordingRequestType.DETAIL:
                return this.getRecording(request.recordingId);
            case RecordingRequestType.METADATA:
                return this.getRecordingMetadata(request.recordingId);
            case RecordingRequestType.BY_CALL_SESSION:
                return this.getRecordingsByCallSessionId(request.callSessionId, request.options);
            default: {
                const exhaustiveCheck = request;
                throw new Error(`Unsupported recording request type: ${JSON.stringify(exhaustiveCheck)}`);
            }
        }
    }
    async getRecordings(options) {
        const loggerContext = {
            file: CALL_RECORDING_FILE,
            method: METHODS.GET_RECORDINGS,
        };
        log.info(`${METHOD_START_MESSAGE} with options=${JSON.stringify(options ?? {})}`, loggerContext);
        let requestUrl = '';
        try {
            requestUrl = await this.buildUserhubRecordingsUrl(options);
            const response = await this.userhubRequest(requestUrl, HTTP_METHODS.GET);
            log.log(`Response trackingId: ${response?.headers?.trackingid}`, loggerContext);
            const body = (response.body ?? {});
            const recordings = (body.recordings ?? body.items ?? [])
                .map(mapUserhubRecording)
                .filter((item) => item.id);
            const responseDetails = {
                statusCode: Number(response.statusCode) || SUCCESS_STATUS_CODE,
                data: {
                    recordings,
                },
                message: SUCCESS_MESSAGE,
            };
            log.log(`Successfully retrieved ${responseDetails.data.recordings?.length ?? 0} recordings`, loggerContext);
            return responseDetails;
        }
        catch (err) {
            const serverDetail = readUserhubErrorDetail(err);
            log.error(`Failed to get recordings: ${serverDetail || JSON.stringify(err)}`, loggerContext);
            await uploadLogs();
            const errorInfo = err;
            const handled = (await serviceErrorCodeHandler(errorInfo, loggerContext));
            if (Number(handled.statusCode) === 500) {
                const detail = [serverDetail || handled.data?.error, requestUrl ? `url=${requestUrl}` : '']
                    .filter((part) => part)
                    .join(' | ');
                if (detail) {
                    handled.data.error = detail;
                }
            }
            else if (serverDetail) {
                handled.data.error = serverDetail;
            }
            return handled;
        }
    }
    async getRecording(recordingId) {
        const loggerContext = {
            file: CALL_RECORDING_FILE,
            method: METHODS.GET_RECORDING,
        };
        log.info(`${METHOD_START_MESSAGE} with recordingId=${recordingId}`, loggerContext);
        try {
            const response = (await this.userhubRequest(this.buildUserhubRecordingUrl(recordingId), HTTP_METHODS.GET, undefined, METHODS.GET_RECORDING));
            log.log(`Response trackingId: ${response?.headers?.trackingid}`, loggerContext);
            const recording = mapUserhubRecording(unwrapUserhubRecording(response.body));
            const responseDetails = {
                statusCode: Number(response.statusCode) || SUCCESS_STATUS_CODE,
                data: {
                    recording,
                },
                message: SUCCESS_MESSAGE,
            };
            log.log(`Successfully retrieved recording ${recordingId}`, loggerContext);
            return responseDetails;
        }
        catch (err) {
            log.error(`Failed to get recording: ${readUserhubErrorDetail(err) || JSON.stringify(err)}`, loggerContext);
            await uploadLogs();
            const errorInfo = err;
            return serviceErrorCodeHandler(errorInfo, loggerContext);
        }
    }
    async getRecordingsByCallSessionId(callSessionId, options) {
        const loggerContext = {
            file: CALL_RECORDING_FILE,
            method: METHODS.GET_RECORDINGS_BY_CALL_SESSION_ID,
        };
        log.info(`${METHOD_START_MESSAGE} with callSessionId=${callSessionId}`, loggerContext);
        const listResponse = await this.getRecordings(options);
        if (listResponse.statusCode !== SUCCESS_STATUS_CODE) {
            return listResponse;
        }
        const filtered = (listResponse.data.recordings ?? []).filter((recording) => recording.serviceData?.callSessionId === callSessionId);
        if (filtered.length === 0) {
            log.info(RECORDING_NOT_FOUND_MESSAGE, loggerContext);
        }
        else {
            log.log(`Successfully retrieved ${filtered.length} recordings for call session ${callSessionId}`, loggerContext);
        }
        return {
            statusCode: SUCCESS_STATUS_CODE,
            data: {
                recordings: filtered,
            },
            message: SUCCESS_MESSAGE,
        };
    }
    async getRecordingMetadata(recordingId) {
        const loggerContext = {
            file: CALL_RECORDING_FILE,
            method: METHODS.GET_RECORDING_METADATA,
        };
        log.info(`${METHOD_START_MESSAGE} with recordingId=${recordingId}`, loggerContext);
        try {
            const response = (await this.userhubRequest(this.buildUserhubRecordingUrl(recordingId), HTTP_METHODS.GET, undefined, METHODS.GET_RECORDING_METADATA));
            log.log(`Response trackingId: ${response?.headers?.trackingid}`, loggerContext);
            const metadata = mapUserhubMetadata(unwrapUserhubRecording(response.body));
            const responseDetails = {
                statusCode: Number(response.statusCode) || SUCCESS_STATUS_CODE,
                data: {
                    metadata,
                },
                message: SUCCESS_MESSAGE,
            };
            log.log(`Successfully retrieved metadata for recording ${recordingId}`, loggerContext);
            return responseDetails;
        }
        catch (err) {
            log.error(`Failed to get recording metadata: ${readUserhubErrorDetail(err) || JSON.stringify(err)}`, loggerContext);
            await uploadLogs();
            const errorInfo = err;
            return serviceErrorCodeHandler(errorInfo, loggerContext);
        }
    }
    async deleteRecording(recordingId, _options) {
        const loggerContext = {
            file: CALL_RECORDING_FILE,
            method: METHODS.DELETE_RECORDING,
        };
        log.info(`${METHOD_START_MESSAGE} with recordingId=${recordingId}`, loggerContext);
        try {
            const response = (await this.userhubRequest(this.buildUserhubSoftDeleteUrl(), HTTP_METHODS.POST, { recordUUIDs: [recordingId] }, METHODS.DELETE_RECORDING));
            log.log(`Response trackingId: ${response?.headers?.trackingid}`, loggerContext);
            const responseDetails = {
                statusCode: Number(response.statusCode) || SUCCESS_STATUS_CODE,
                data: {},
                message: SUCCESS_MESSAGE,
            };
            log.log(`Successfully moved recording ${recordingId} to recycle bin`, loggerContext);
            return responseDetails;
        }
        catch (err) {
            log.error(`Failed to delete recording: ${readUserhubErrorDetail(err) || JSON.stringify(err)}`, loggerContext);
            await uploadLogs();
            const errorInfo = err;
            return serviceErrorCodeHandler(errorInfo, loggerContext);
        }
    }
    handleRecordingCreatedEvent = async (event) => {
        if (!event?.data?.activity) {
            return;
        }
        this.emit(COMMON_EVENT_KEYS.CALL_RECORDING_CREATED, event);
    };
    handleRecordingUpdatedEvent = async (event) => {
        if (!event?.data?.activity) {
            return;
        }
        switch (event.data.eventSubType) {
            case RECORDING_EVENT_SUBTYPE.TRASH:
            case RECORDING_EVENT_SUBTYPE.PURGE:
                this.emit(COMMON_EVENT_KEYS.CALL_RECORDING_DELETED, event);
                break;
            case RECORDING_EVENT_SUBTYPE.RESTORE:
                this.emit(COMMON_EVENT_KEYS.CALL_RECORDING_CREATED, event);
                break;
            default:
                this.emit(COMMON_EVENT_KEYS.CALL_RECORDING_UPDATED, event);
        }
    };
    handleRecordingDeletedEvent = async (event) => {
        if (!event?.data?.activity) {
            return;
        }
        this.emit(COMMON_EVENT_KEYS.CALL_RECORDING_DELETED, event);
    };
    registerRecordingListeners() {
        this.sdkConnector.registerListener(MOBIUS_EVENT_KEYS.RECORDING_EVENT_CREATED, this.handleRecordingCreatedEvent);
        this.sdkConnector.registerListener(MOBIUS_EVENT_KEYS.RECORDING_EVENT_UPDATED, this.handleRecordingUpdatedEvent);
        this.sdkConnector.registerListener(MOBIUS_EVENT_KEYS.RECORDING_EVENT_DELETED, this.handleRecordingDeletedEvent);
    }
}
